from __future__ import annotations

import os
from pathlib import Path


def main() -> None:
    challenge_root = Path(os.environ["BRUNNER_CHALLENGE_ROOT"])
    resource_root = challenge_root / "resources"
    resource_root.mkdir(parents=True, exist_ok=True)
    (resource_root / "materialized-note.txt").write_text(
        "This candidate-visible resource was generated by the example "
        "materializer.\n"
    )


if __name__ == "__main__":
    main()
